func (v Certainty) valid() bool { return v > 0 && int(v) < len(certaintyNames) }

func (v Certainty) String() string {
	if v == CertaintyUnset {
		return "CertaintyUnset"
	}
	if v.valid() {
		return certaintyNames[v]
	}
	return fmt.Sprintf("Certainty(%d)", uint8(v))
}

func (v Certainty) MarshalJSON() ([]byte, error) {
	if !v.valid() {
		return nil, fmt.Errorf("%v is not a certainty", v)
	}
	return json.Marshal(certaintyNames[v])
}

func (v *Certainty) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return err
	}
	p, err := ParseCertainty(s)
	if err != nil {
		return err
	}
	*v = p
	return nil
}

// ParseCertainty reads the name of a certainty, as the JSON writes it.
func ParseCertainty(s string) (Certainty, error) {
	for i, n := range certaintyNames {
		if v := Certainty(i); n == s && v.valid() {
			return v, nil
		}
	}
	return CertaintyUnset, fmt.Errorf("%q is not a certainty (confirmed, conditional, inconclusive)", s)
}

// The values of $defs/input-state, in the order of the schema. The zero value is the first.
const (
	// InputStateRead: Read, and GitHub would take it.
	InputStateRead InputState = iota
	// InputStateUnreadable: Not read: the bytes could not be read, or are not UTF-8.
	InputStateUnreadable
	// InputStateInvalid: Read, but GitHub would not take it: diagnostics, or a symlink workflow.
	InputStateInvalid
	// InputStateExcluded: Left out by --exclude: not read.
	InputStateExcluded
)

var inputStateNames = [...]string{"read", "unreadable", "invalid", "excluded"}

var inputStateDescriptions = [...]string{"Read, and GitHub would take it.", "Not read: the bytes could not be read, or are not UTF-8.", "Read, but GitHub would not take it: diagnostics, or a symlink workflow.", "Left out by --exclude: not read."}

// description is what v is, as the source of the enumeration says; empty
