// Facets is $defs/facets: The values of the rule on each axis that sorts the rules, for people to find rules alike; they change nothing the rule reports. Each axis is a property, and has one value at least, each once (actions/lint checks it); actions/lint generates its Go type and the enumeration of its axes from these properties.
type Facets struct {
	Weakness    []Weakness    `json:"weakness"`
	AttackMeans []AttackMeans `json:"attack_means"`
}

var facetKeys = [...]string{"", "weakness", "attack_means"}

// Key is the key of the axis v in the JSON of Facets; empty for what is
// not an axis.
func (v Facet) Key() string {
	if v.valid() {
		return facetKeys[v]
	}
	return ""
}

// Description is what the axis v is, as the schema says.
func (v Facet) Description() string { return v.description() }

// Description is what v is, as the schema says.
func (v Weakness) Description() string { return v.description() }

// Description is what v is, as the schema says.
func (v AttackMeans) Description() string { return v.description() }

// FacetValue is a value of an axis of Facets.
type FacetValue interface {
	fmt.Stringer
	json.Marshaler
	Description() string
	valid() bool
}

// FacetAxis is an axis of Facets and values of it.
type FacetAxis struct {
	Facet  Facet
	Values []FacetValue
}

// Axes are the axes of x, in the order of the schema, each with the values
// x has.
func (x Facets) Axes() []FacetAxis {
	return []FacetAxis{
		{FacetWeakness, facetValuesOf(x.Weakness)},
		{FacetAttackMeans, facetValuesOf(x.AttackMeans)},
	}
}

// facetsAll is Facets with every value of each axis.
func facetsAll() Facets {
	return Facets{Weakness: weaknessValues(), AttackMeans: attackMeansValues()}
}

func facetValuesOf[T FacetValue](vs []T) []FacetValue {
	out := make([]FacetValue, 0, len(vs))
	for _, v := range vs {
		out = append(out, v)
	}
	return out
}
